pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 receiveCalls) public {
        // Bound the number of receive calls to avoid numeric overflow issues in the loop
        // while keeping the domain wide enough to trigger the difference (any calls >= 1).
        vm.assume(receiveCalls >= 0);
        receiveCalls = bound(receiveCalls, 0, 1e5);

        // Perform N receive() calls, each sending 0.001 ether
        vm.deal(address(this), receiveCalls * 0.001 ether + 1 ether);
        for (uint256 i = 0; i < receiveCalls; i++) {
            (bool ok,) = address(c).call{value: 0.001 ether}("");
            require(ok, "receive should not revert");
        }

        // depositsCount must equal the number of receive calls
        assertTrue(c.depositsCount() == receiveCalls);
    }
}

