pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositCount) public {
        // Bound depositCount to a reasonable range for gas considerations
        // but still allow the fuzzer to test overflow scenarios.
        vm.assume(depositCount <= 1000);

        // Perform the given number of deposits
        for (uint256 i = 0; i < depositCount; i++) {
            // Use a tiny amount to avoid needing excessive ETH
            (bool success,) = address(c).call{value: 1 wei}("");
            if (!success) {
                // If a deposit reverts (due to overflow), stop depositing.
                // The reference should revert on overflow, buggy won't.
                break;
            }
        }

        // After all deposits, the depositsCount should equal the number
        // of successful calls, and never exceed depositCount.
        // For the reference: depositsCount == number of successful deposits <= depositCount.
        // For the buggy: depositsCount can wrap around and be less than the number of successful deposits,
        // or incorrectly increment on overflow.
        assertTrue(c.depositsCount() <= depositCount);
    }
}

