pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preBalance) public {
        // preBalance is the intended depositsCount to reach before triggering a potential overflow
        bound(preBalance, 0, type(uint256).max - 1);
        // Drive depositsCount to preBalance via pranked sends (each increments by 1)
        for (uint256 i = 0; i < preBalance; i++) {
            vm.deal(address(this), 1);
            vm.prank(address(this));
            (bool ok,) = address(c).call{value: 1}("");
            require(ok, "pre-deposit failed");
        }
        // Record current depositsCount
        uint256 beforeCount = c.depositsCount();
        // Attempt one more deposit, which might overflow in buggy version when beforeCount == type(uint256).max
        vm.deal(address(this), 1);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: 1}("");
        if (ok) {
            // If the call succeeded, depositsCount must strictly increase (no wrap)
            assertTrue(c.depositsCount() > beforeCount);
        } else {
            // If the call reverted (original behaviour on overflow), depositsCount must remain unchanged
            assertTrue(c.depositsCount() == beforeCount);
        }
    }
}

