pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preCount, uint256 delta) public {
        // preCount is the number of deposits to perform before the critical one.
        // delta is how many more deposits we need to reach overflow on the final call.
        // Bound preCount to a wide range, but allow the fuzzer to reach near-max values.
        bound(preCount, 0, type(uint256).max - 1);
        // delta must be such that preCount + delta + 1 will overflow depositsCount.
        // We allow the fuzzer to pick delta; we restrict it to a reasonable range to make the search feasible.
        bound(delta, 0, type(uint256).max - 1);
        // Ensure the final deposit index (preCount + delta) plus 1 would overflow.
        vm.assume(preCount <= type(uint256).max - delta);
        uint256 overflowTarget = preCount + delta;
        vm.assume(overflowTarget < type(uint256).max);

        // Perform preCount deposits.
        for (uint256 i = 0; i < preCount; i++) {
            vm.deal(address(this), 1 ether);
            vm.prank(address(this));
            (bool ok, ) = address(c).call{value: 1}("");
            require(ok, "deposit failed");
        }
        // Perform delta more deposits, leaving depositsCount at overflowTarget.
        for (uint256 i = 0; i < delta; i++) {
            vm.deal(address(this), 1 ether);
            vm.prank(address(this));
            (bool ok, ) = address(c).call{value: 1}("");
            require(ok, "deposit failed");
        }

        // Record the state before the final, overflow-triggering call.
        uint256 beforeDeposits = c.depositsCount();
        // Ensure we are exactly at the point where one more deposit overflows uint256.
        vm.assume(beforeDeposits == type(uint256).max);

        // Perform the final deposit that, in reference, should revert due to overflow check.
        // In the buggy version it will not revert and depositsCount will wrap to 0.
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool finalOk, ) = address(c).call{value: 1}("");

        if (finalOk) {
            // The call succeeded; in the reference this should never happen.
            // If it succeeded, depositsCount must be strictly greater than before the call.
            uint256 afterDeposits = c.depositsCount();
            assertTrue(afterDeposits > beforeDeposits);
        } else {
            // The call reverted (reference behavior). No assertion needed; this is fine.
            assertTrue(true);
        }
    }
}

