pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 preDeposits, uint256 sendValue) public {
        // Bound preDeposits to the maximum possible depositsCount so we can directly set it.
        // We test the critical state: depositsCount == type(uint).max.
        preDeposits = bound(preDeposits, type(uint).max, type(uint).max);
        // sendValue is any non-zero value to trigger receive.
        sendValue = bound(sendValue, 1, type(uint128).max);

        // Set the depositsCount to the bound value (which is type(uint).max).
        // We achieve this by using vm.store to directly write the storage slot of depositsCount.
        // depositsCount is the second state variable (slot 1).
        bytes32 slot = bytes32(uint256(1));
        vm.store(address(c), slot, bytes32(preDeposits));

        // Record balance before the call (not used in assertion but helps setup).
        // Give the sender enough ether.
        address sender = address(0x1234);
        vm.deal(sender, sendValue);

        bool refSuccess;
        vm.prank(sender);
        try c{value: sendValue}() {
            refSuccess = true;
        } catch {
            refSuccess = false;
        }

        // The general rule: if the call does not revert, depositsCount must be > preDeposits.
        // When preDeposits is type(uint).max, a non-reverting call would require depositsCount to be > max,
        // which is impossible because addition wraps. The reference contract reverts,
        // so the implication (success => depositsCount > preDeposits) vacuously holds.
        // The mutant never reverts and wraps depositsCount to 0, violating the condition.
        assertTrue(!refSuccess || c.depositsCount() > preDeposits);
    }
}

